583	  function seasonOpenOn(text, when) {
584	    var t = String(text || "");
585	    if (!t) return null;
586	    if (/CLOSED\s+ALL\s+YEAR/i.test(t)) return false;
587	    if (/OPEN\s+ALL\s+YEAR/i.test(t)) return true;
588	    /* A season can name more than one range: "OPEN MAY 15 TO OCT. 31 AND
589	     * DEC. 11 TO MAR. 31". Reading only the first range shut that lake all
590	     * winter, so every range is read and any one of them opens the day. */
591	    var re = /([A-Za-z]+)\.?\s+(\d{1,2})\s+TO\s+([A-Za-z]+)\.?\s+(\d{1,2})/gi;
592	    if (!/^\s*OPEN\b/i.test(t)) return null;
593	    var at = function (mo, d) { return mo * 100 + d; };
594	    var day = when instanceof Date ? when : new Date();
595	    var now = at(day.getMonth(), day.getDate());
596	    var m, found = false;
597	    while ((m = re.exec(t)) !== null) {
598	      var from = MONTHS.indexOf(m[1].slice(0, 3).toLowerCase());
599	      var to = MONTHS.indexOf(m[3].slice(0, 3).toLowerCase());
600	      if (from < 0 || to < 0) return null;
601	      found = true;
602	      var start = at(from, Number(m[2])), end = at(to, Number(m[4]));
603	      var open = start <= end ? (now >= start && now <= end)
604	                              : (now >= start || now <= end);
605	      if (open) return true;
606	    }
607	    return found ? false : null;
